 bf_pdf_open(paste0(F,'.pdf'),q$width_mm,q$height_mm,font);print(p);mm<-measure();dev.off();jsonlite::write_json(mm,file.path(w,'actual-pdf-cell-metrics.json'),auto_unbox=TRUE,pretty=TRUE,digits=NA);jsonlite::write_json(bf_pdf_finalize(paste0(F,'.pdf'),font,q$width_mm,q$height_mm),file.path(w,'pdf-technical-audit.json'),auto_unbox=TRUE,pretty=TRUE);capture.output(sessionInfo(),file=file.path(w,'render-sessionInfo.txt'));cat(key,'formal render completed; visual review pending\n')
